package com.meridian.keystone.security; import io.jsonwebtoken.*; import org.springframework.stereotype.Component; import java.util.Date; @Component public class JwtUtil { String SECRET="MySuperSecretKeyForKeystoneProject32CharsLong123456"; long EXP=86400000; public String gen(String email,String role){return Jwts.builder().setSubject(email).claim("role",role).setIssuedAt(new Date()).setExpiration(new Date(System.currentTimeMillis()+EXP)).signWith(SignatureAlgorithm.HS256,SECRET).compact();} public String getEmail(String t){return Jwts.parser().setSigningKey(SECRET).parseClaimsJws(t).getBody().getSubject();} }
